#include <stdio.h>
#include <stdlib.h>

#define MAX 100

typedef struct {
    int data[MAX];
    int size;
} MinHeap;

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

void heapifyUp(MinHeap *h, int index) {
    while (index > 0) {
        int parent = (index - 1) / 2;
        if (h->data[index] < h->data[parent]) {
            swap(&h->data[index], &h->data[parent]);
            index = parent;
        } else {
            break;
        }
    }
}

void heapifyDown(MinHeap *h, int index) {
    int smallest = index;
    int left = 2 * index + 1;
    int right = 2 * index + 2;

    if (left < h->size && h->data[left] < h->data[smallest])
        smallest = left;
    if (right < h->size && h->data[right] < h->data[smallest])
        smallest = right;

    if (smallest != index) {
        swap(&h->data[index], &h->data[smallest]);
        heapifyDown(h, smallest);
    }
}

void insert(MinHeap *h, int val) {
    if (h->size >= MAX) {
        printf("Heap Overflow!\n");
        return;
    }
    h->data[h->size] = val;
    heapifyUp(h, h->size);
    h->size++;
}

int extractMin(MinHeap *h) {
    if (h->size <= 0) {
        printf("Heap Underflow!\n");
        return -1;
    }
    int root = h->data[0];
    h->data[0] = h->data[h->size - 1];
    h->size--;
    heapifyDown(h, 0);
    return root;
}

int main(void) {
    MinHeap h = {.size = 0};
    insert(&h, 30);
    insert(&h, 10);
    insert(&h, 50);
    insert(&h, 5);
    insert(&h, 20);

    printf("Min-Heap extracted in ascending order: ");
    while (h.size > 0) {
        printf("%d ", extractMin(&h));
    }
    printf("\n");
    return 0;
}
